zip_path = WORKDIR / "environments.zip"
with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as z:
    for f in OUT.rglob("*"):
        if f.is_file():
            z.write(f, f.relative_to(OUT))
print("ZIP:", zip_path, f"({zip_path.stat().st_size/1024:.0f} KB)")
print("Files under /kaggle/working are saved as the notebook output automatically.")
